function validate([n, logs]) {
  if (!Number.isInteger(n) || n < 2 || n > 500) return 'n is an integer from 2 to 500.';
  if (!Array.isArray(logs) || logs.length < 1 || logs.length > 500) return 'logs needs 1 to 500 entries.';
  for (let i = 0; i < logs.length; i++) {
    const entry = logs[i];
    if (!Array.isArray(entry) || entry.length !== 2) return 'Each log is a pair [id, leaveTime].';
    const [id, leaveTime] = entry;
    if (!Number.isInteger(id) || id < 0 || id > n - 1) return 'Each id is between 0 and n - 1.';
    if (!Number.isInteger(leaveTime) || leaveTime < 1 || leaveTime > 500) return 'Each leaveTime is between 1 and 500.';
    if (i > 0 && logs[i - 1][0] === id) return 'Two consecutive tasks must have different ids.';
    if (i > 0 && logs[i - 1][1] >= leaveTime) return 'Finish times must strictly increase.';
  }
  return null;
}

