function hardestWorker(n, logs) {
  let bestId = n;
  let longest = 0;
  let start = 0;

  for (const [id, leaveTime] of logs) {
    const duration = leaveTime - start;
    if (duration > longest || (duration === longest && id < bestId)) {
      longest = duration;
      bestId = id;
    }
    start = leaveTime;
  }
  return bestId;
}

