function hardestWorker(n, logs) {
  const most = new Array(n).fill(0);
  for (let i = 0; i < logs.length; i++) {
    const begin = i === 0 ? 0 : logs[i - 1][1];
    const length = logs[i][1] - begin;
    most[logs[i][0]] = Math.max(most[logs[i][0]], length);
  }
  let answer = 0;
  for (let id = 1; id < n; id++) {
    if (most[id] > most[answer]) answer = id;
  }
  return answer;
}

