function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? pick(400, 500) : pick(2, 5);
  const maxTime = size === 'large' ? 500 : pick(1, 20);
  const m = size === 'large' ? pick(150, 450) : pick(1, Math.min(8, maxTime));
  const times = [];
  for (let t = 1; t <= maxTime; t++) times.push(t);
  for (let i = times.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [times[i], times[j]] = [times[j], times[i]];
  }
  const chosen = times.slice(0, m).sort((a, b) => a - b);
  const logs = [];
  let previous = -1;
  for (const leaveTime of chosen) {
    let id = pick(0, n - 1);
    while (id === previous) id = pick(0, n - 1);
    logs.push([id, leaveTime]);
    previous = id;
  }
  return [n, logs];
}
